import { createRouter, createWebHistory } from 'vue-router'
import { $storex } from '../store'
import Navigate from './navigate'
import QuickChatView from '@/views/QuickChatView.vue'
import WorkspaceView from '@/views/WorkspaceView.vue'
import MessengerView from '@/views/MessengerView.vue'
import MeetView from '@/views/MeetView.vue'
import MetricsDashboard from '@/components/analytics/MetricsDashboard.vue'
import Desktop from '@/components/desktop/Desktop.vue'
import KanbanBoardView from '@/components/kanban/board/KanbanBoardView.vue'
import BrowsersSessionManager from '@/components/browsers/BrowsersSessionManager.vue'
import TeamView from '@/views/TeamView.vue'
import AppRouteView from '@/views/AppRouteView.vue'

// ─────────────────────────────────────────────────────────────────────────────
// PROJECT-SCOPED ROUTES
// Every route is mounted under the active project's *escaped* name so the URL
// always reflects which project you are working in, e.g.
//   /codx-junior/chats      → project "codx-junior" chat list
//   /my.project/desktop     → project "my.project"  desktop view
//   /my-project/settings    → project "my-project"  settings
// The first segment is the project_name; vue-router percent-encodes it while
// building the URL, so names containing dots, dashes, spaces… stay valid.
// ─────────────────────────────────────────────────────────────────────────────

// Return the RAW active project name. vue-router encodes route params when it
// builds the URL, so pre-encoding here would double-encode names with special
// characters (e.g. "my project" → "my%2520project"), and the segment would no
// longer decode back to the real project name on reload.
function activeProjectSegment() {
  return $storex.projects.activeProject?.project_name || ''
}

const router = createRouter({
  history: createWebHistory(import.meta.env.BASE_URL),
  routes: [
    {
      // Unscoped bootstrap home. The navigation guard replaces it with the
      // project-scoped home ("/:projectName") as soon as a project is active.
      path: '/',
      name: 'root',
      component: QuickChatView
    },
    {
      // Home (project launcher)
      path: '/:projectName',
      name: 'home',
      component: QuickChatView
    },
    {
      // Chat routes: router mode
      path: '/:projectName/chats',
      name: 'chats',
      component: QuickChatView
    },
    {
      path: '/:projectName/chats/:chatId/:chatName',
      name: 'chat',
      component: QuickChatView
    },
    {
      path: '/:projectName/chats/:chatId/:chatName/workspace/:workspaceId/:workspaceName',
      name: 'chat-workspace',
      component: QuickChatView
    },
    {
      // Meet routes: router mode
      path: '/:projectName/meet',
      name: 'meet',
      component: MeetView
    },
    {
      path: '/:projectName/meet/:meetId',
      name: 'meet-session',
      component: MeetView
    },
    {
      // Workspace routes: router mode
      path: '/:projectName/workspaces',
      name: 'workspaces',
      component: WorkspaceView
    },
    {
      path: '/:projectName/workspaces/:workspaceId/:workspaceName',
      name: 'workspace',
      component: WorkspaceView
    },
    {
      // Browser routes: router mode
      path: '/:projectName/browsers',
      name: 'browsers',
      component: BrowsersSessionManager
    },
    {
      path: '/:projectName/browsers/:sessionId/:sessionName',
      name: 'browser-session',
      component: BrowsersSessionManager
    },
    {
      // The optional board id + name segments let the URL carry the open board,
      // so a refresh or a back-navigation (non-desktop / single mode) reopens it.
      // Both are optional: the plain "/:projectName/kanban" still works.
      path: '/:projectName/kanban/:board?/:boardName?',
      name: 'kanban',
      component: KanbanBoardView
    },
    {
      path: '/:projectName/messenger',
      name: 'messenger',
      component: MessengerView
    },
    {
      // Team view (used by setActiveTab('team') / openTeam())
      path: '/:projectName/team',
      name: 'team',
      component: TeamView
    },

    // ── Generic app routes ────────────────────────────────────────────────
    // Each app maps to <AppRouteView> which resolves the component from
    // config/apps.js (route meta.app) and feeds it its params.
    { path: '/:projectName/vibe-coding', name: 'vibe-coding', component: AppRouteView, meta: { app: 'vibe-coding' } },
    { path: '/:projectName/wiki', name: 'wiki', component: AppRouteView, meta: { app: 'wiki' } },
    { path: '/:projectName/docs', name: 'docs', component: AppRouteView, meta: { app: 'docs' } },
    { path: '/:projectName/knowledge', name: 'knowledge', component: AppRouteView, meta: { app: 'knowledge' } },
    { path: '/:projectName/knowledge-settings', name: 'knowledge-settings', component: AppRouteView, meta: { app: 'knowledge_settings' } },
    { path: '/:projectName/profiles', name: 'profiles', component: AppRouteView, meta: { app: 'profiles' } },
    { path: '/:projectName/projects', name: 'projects', component: AppRouteView, meta: { app: 'projects' } },
    { path: '/:projectName/activity', name: 'activity', component: AppRouteView, meta: { app: 'activity' } },
    { path: '/:projectName/settings', name: 'settings', component: AppRouteView, meta: { app: 'settings' } },
    { path: '/:projectName/global-settings', name: 'global-settings', component: AppRouteView, meta: { app: 'global-settings' } },
    { path: '/:projectName/account', name: 'account', component: AppRouteView, meta: { app: 'account' } },
    { path: '/:projectName/file-explorer', name: 'file-explorer', component: AppRouteView, meta: { app: 'file-explorer' } },
    { path: '/:projectName/file-viewer/:filePath(.*)*', name: 'file-viewer', component: AppRouteView, meta: { app: 'file-viewer' } },
    { path: '/:projectName/logs', name: 'log-viewer', component: AppRouteView, meta: { app: 'log-viewer' } },
    { path: '/:projectName/chat-logs', name: 'chat-logs', component: AppRouteView, meta: { app: 'chat-logs' } },
    { path: '/:projectName/metrics', name: 'metrics', component: AppRouteView, meta: { app: 'metrics' } },
    { path: '/:projectName/team-channel/:channelId', name: 'team-channel', component: AppRouteView, meta: { app: 'team-channel' } },
    { path: '/:projectName/team-dm/:dmId', name: 'team-dm', component: AppRouteView, meta: { app: 'team-dm' } },
    { path: '/:projectName/team-media-library/:teamId', name: 'team-media-library', component: AppRouteView, meta: { app: 'team-media-library' } },

    {
      // Desktop / team view (dockview panels)
      path: '/:projectName/desktop/:pathMatch(.*)*',
      name: 'codx-junior-split',
      component: Desktop
    },
    {
      path: '/:projectName/analytics',
      name: 'analytics',
      component: MetricsDashboard
    },
    {
      // Catch-all: redirect everything else to the project bootstrap
      path: '/:pathMatch(.*)*',
      redirect: '/'
    },
  ]
})

// ─────────────────────────────────────────────────────────────────────────────
// BASE-PATH ENFORCEMENT
// Any navigation by *name* to a project-scoped route automatically gets the
// active project name injected as the first URL segment. Centralising it here
// means call sites only ever specify the route name/params, and the project
// prefix is never forgotten (works for $router.push, $router.replace and
// <RouterLink> alike, since they all funnel through these two methods).
// ─────────────────────────────────────────────────────────────────────────────

// Names of routes that live under the "/:projectName" base path.
let scopedRouteNames = new Set()

function refreshScopedRouteNames() {
  scopedRouteNames = new Set(
    router.getRoutes()
      .filter(route => typeof route.name === 'string' && route.path.includes(':projectName'))
      .map(route => route.name)
  )
}

function withProject(location: any): any {
  // String paths are already fully qualified (or external) – leave them as-is.
  if (!location || typeof location === 'string') {
    return location
  }
  const loc = { ...location }
  if (scopedRouteNames.has(loc.name) && !(loc.params && loc.params.projectName)) {
    loc.params = { ...(loc.params || {}), projectName: activeProjectSegment() }
  }
  return loc
}

refreshScopedRouteNames()

const _push = router.push.bind(router)
const _replace = router.replace.bind(router)
;(router as any).push = (to: any) => _push(withProject(to))
;(router as any).replace = (to: any) => _replace(withProject(to))

// Initialize navigation API with both $router and $storex
router.$navigation = Navigate({ $router: router, $storex })
router.$navigation.init()

router.beforeEach((to, from) => {
  return router.$navigation.onRouteChanged({ from, to })
})

$storex.$router = router
$storex.$navigation = router.$navigation

export default router

// ─────────────────────────────────────────────────────────────────────────────
// Single source of truth for "how to open an app".
//
// Each entry describes an app that can be opened either:
//   • as a desktop dockview PANEL  (expert view mode / desktop screens), or
//   • as a mobile ROUTE            (mobile screens / router mode).
//
// `openApp(appKey, payload)` (see router/navigate.js) reads this registry and
// picks the right strategy, so the rest of the app never needs to branch on
// isMobile / isDesktopMode again.
// ─────────────────────────────────────────────────────────────────────────────

// Transient payload hand-off for mobile routes. Some apps need rich objects
// (a chat, a team member, a workspace…) that can't be encoded in the URL.
// `openApp` stashes them here and <AppRouteView> reads them back per app.
const PENDING = {}

export function setPendingParams(appId, params) {
  PENDING[appId] = params
}

export function getPendingParams(appId) {
  return PENDING[appId] || null
}

export function clearPendingParams(appId) {
  delete PENDING[appId]
}

// ─────────────────────────────────────────────────────────────────────────────
// MULTI-INSTANCE APPS
//
// By default an app is SINGLE-INSTANCE: opening it again focuses the panel that
// is already open (the UI store de-duplicates by the app's `key`).
//
// Apps that may legitimately live in more than one panel at a time opt in with:
//
//     multiInstance: true
//
// Their per-instance identity is described with the same helpers used by every
// other app — `desktopKey` / `desktopTabId` / `desktopParams`. For example a
// Task Manager instance is a single BOARD, so several boards can be open side by
// side while re-opening the same board just focuses its existing panel.
// ─────────────────────────────────────────────────────────────────────────────

export const APPS = {
  // ── Primary apps ──────────────────────────────────────────────────────────
  home: {
    id: 'home', title: 'Home', component: 'home', icon: 'fa-solid fa-home',
    route: () => ({ name: 'home' })
  },

  tasks: {
    id: 'tasks', title: 'Task Manager', component: 'tasks', icon: 'fa-brands fa-trello',
    // Several Task Managers can be open at once — one per board. The board is
    // what identifies each instance, so different boards become independent
    // panels while re-opening the same board (or opening with no board at all)
    // just focuses the panel that is already showing it.
    multiInstance: true,
    desktopKey: p => (p.board ? `tasks-${p.board}` : 'tasks'),
    desktopTabId: p => (p.board ? `tasks-${p.board}` : undefined),
    desktopParams: p => ({ board: p.board }),
    // Single (non-desktop) mode keeps the open board in the ROUTE (id + name), so
    // refreshing the page or coming back from another route reopens that board
    // (see router/index.ts: "/:projectName/kanban/:board?/:boardName?").
    route: p => ({
      name: 'kanban',
      params: {
        ...(p.board ? { board: p.board } : {}),
        ...(p.boardName ? { boardName: p.boardName } : {})
      }
    })
  },

  planning: {
    id: 'planning', title: 'Planning', component: 'tasks', icon: 'fa-solid fa-diagram-project',
    desktopParams: () => ({ view: 'planning' }),
    route: () => ({ name: 'kanban', query: { view: 'planning' } })
  },

  chat: {
    id: 'chat', title: 'Chat', component: 'chat', icon: 'fa-regular fa-comments',
    desktopKey: p => (p.chat?.id ? `chat-${p.chat.id}` : undefined),
    desktopTabId: p => p.chat?.id,
    desktopParams: p => ({ chat: p.chat, ...(p.workspace ? { workspace: p.workspace } : {}) }),
    route: p => p.workspace
      ? { name: 'chat-workspace', params: { chatId: p.chat?.id, chatName: p.chat?.name, workspaceId: p.workspace.id, workspaceName: p.workspace.name } }
      : { name: 'chat', params: { chatId: p.chat?.id, chatName: p.chat?.name || `chat-${p.chat?.id}` } }
  },

  messenger: {
    id: 'messenger', title: 'Messenger', component: 'messenger', icon: 'fa-regular fa-comments',
    route: () => ({ name: 'messenger' })
  },

  meet: {
    id: 'meet', title: 'Meet', component: 'meet', icon: 'fa-solid fa-video',
    desktopParams: p => ({ meetId: p.meetId }),
    route: p => p.meetId
      ? { name: 'meet-session', params: { meetId: p.meetId } }
      : { name: 'meet' }
  },

  team: {
    id: 'team', title: 'Team', component: 'team', icon: 'fa-solid fa-people-group',
    route: () => ({ name: 'team' })
  },

  // ── Workspaces & browsers ─────────────────────────────────────────────────
  workspaces: {
    id: 'workspaces', title: 'Workspaces', component: 'workspaces', icon: 'fa-solid fa-server',
    route: () => ({ name: 'workspaces' })
  },

  workspace: {
    id: 'workspace', title: 'Workspace', component: 'workspace', icon: 'fa-regular fa-window-maximize',
    desktopKey: p => `workspace-${p.workspace?.key}`,
    desktopTabId: p => `workspace-${p.workspace?.key}`,
    // Expose the workspace under the semantic `workspace` key (same convention
    // as `chat`) so name / path reach the Tab and AppWindow readers, which look
    // up `params.params.workspace` directly.
    desktopParams: p => ({ workspace: p.workspace }),
    route: p => ({ name: 'workspace', params: { workspaceId: p.workspace?.key, workspaceName: p.workspace?.name } })
  },

  'browser-sessions': {
    id: 'browser-sessions', title: 'Browser Sessions', component: 'browser-sessions', icon: 'fa-regular fa-compass',
    route: () => ({ name: 'browsers' })
  },

  // ── Files ─────────────────────────────────────────────────────────────────
  'file-explorer': {
    id: 'file-explorer', title: 'File Explorer', component: 'file-explorer', icon: 'fa-solid fa-folder-open',
    route: () => ({ name: 'file-explorer' })
  },

  'file-viewer': {
    id: 'file-viewer', title: 'File', component: 'file-viewer', icon: 'fa-regular fa-file',
    desktopKey: p => (p.filePath ? `file-viewer-${p.filePath}` : undefined),
    desktopTabId: p => (p.filePath ? `file-viewer-${p.filePath}` : undefined),
    desktopParams: p => ({ filePath: p.filePath }),
    route: p => ({ name: 'file-viewer', params: { filePath: p.filePath } })
  },

  // ── Git ───────────────────────────────────────────────────────────────────
  'git-view': {
    id: 'git-view', title: 'Git', component: 'git-view', icon: 'fa-solid fa-code-branch',
    route: () => ({ name: 'git-view' })
  },

  // ── Knowledge / docs ──────────────────────────────────────────────────────
  wiki: {
    id: 'wiki', title: 'Wiki', component: 'wiki', icon: 'fa-solid fa-graduation-cap',
    route: () => ({ name: 'wiki' })
  },

  docs: {
    id: 'docs', title: 'Docs', component: 'docs', icon: 'fa-solid fa-book',
    route: () => ({ name: 'docs' })
  },

  knowledge: {
    id: 'knowledge', title: 'Knowledge', component: 'knowledge', icon: 'fa-solid fa-magnifying-glass',
    desktopParams: p => ({ ...(p.params || {}) }),
    route: () => ({ name: 'knowledge' })
  },

  knowledge_settings: {
    id: 'knowledge_settings', title: 'Knowledge Settings', component: 'knowledge_settings', icon: 'fa-solid fa-sliders',
    route: () => ({ name: 'knowledge-settings' })
  },

  // ── Project & user ────────────────────────────────────────────────────────
  profiles: {
    id: 'profiles', title: 'Profiles', component: 'profiles', icon: 'fa-solid fa-id-badge',
    route: () => ({ name: 'profiles' })
  },

  projects: {
    id: 'projects', title: 'Projects', component: 'projects', icon: 'fa-solid fa-cubes',
    route: () => ({ name: 'projects' })
  },

  activity: {
    id: 'activity', title: 'Activity', component: 'activity', icon: 'fa-solid fa-clock-rotate-left',
    desktopParams: p => ({ project: p.project, board: p.board }),
    route: () => ({ name: 'activity' })
  },

  settings: {
    id: 'settings', title: 'Project Settings', component: 'settings', icon: 'fa-solid fa-gear',
